BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('SP106-1-08','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-02-18。本題考身心障礙者權利公約第23條第5項：締約國應於直系親屬不能照顧身心障礙兒童之情況下，盡一切努力於家族範圍內提供替代性照顧，並於無法提供該等照顧時，於社區內提供家庭式照顧。屬公約本文，未經修正；身心障礙者權利公約施行法第2條（公約具國內法律之效力）自 2014-08-20 制定公布、2014-12-03 施行後亦未修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050194'),('SP108-1-35','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2019-01-19。本題考兒童及少年未來教育與發展帳戶條例第16條：直轄市、縣（市）主管機關應於開戶人滿十八歲「一個月前」通知其辦理帳戶款項之請領並結清帳戶，選項(A)「三個月前」錯誤；儲金用途以就學、就業、職業訓練或創業為限，開戶人滿十八歲之日起十年內因死亡或未申請提領之處理，均與條文相符。本條例於 2018-06-06 制定公布施行，其後未曾修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050205'),('SP108-2-40','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2019-07-27。本題考兒童及少年未來教育與發展帳戶條例第22條：直轄市、縣（市）主管機關得結合民間資源，運用社會工作人員，對連續三至六個月未存款之開戶人、法定代理人或最近親屬進行輔導及提供相關協助，不包括請學校教師輔導。本條例於 2018-06-06 制定公布施行，其後未曾修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050205'),('SP109-1-40','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2020-02-15。本題考兒童及少年未來教育與發展帳戶條例第11條：開戶金及自存款年度存款上限金額得每四年調整一次。本條例於 2018-06-06 制定公布施行，其後未曾修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050205'),('SP110-2-06','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2021-08-21。本題考身心障礙者權利公約第3條一般原則：尊重自主、不歧視、充分有效參與及融合社會、尊重差異、機會均等、無障礙、男女平等、尊重身心障礙兒童逐漸發展之能力及保持身分認同之權利，不含「尊重老人」。屬公約本文，未經修正；身心障礙者權利公約施行法第2條（公約具國內法律之效力）自 2014-08-20 制定公布、2014-12-03 施行後亦未修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050194'),('SP111-2-34','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2022-07-30。本題考兒童及少年未來教育與發展帳戶條例第22條：直轄市、縣（市）主管機關得對連續三至六個月未存款之開戶人、法定代理人或最近親屬進行輔導及提供相關協助。本條例於 2018-06-06 制定公布施行，其後未曾修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050205'),('SP111-2-40','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2022-07-30。本題考長期照顧服務機構法人條例第10條：長照機構財團法人所登記之財產總額或該法人及其所設立機構之年度收入總額達新臺幣一億元以上者，主管機關應指派社會公正人士一人擔任公益監察人。本條例於 2018-01-31 制定公布，其後未曾修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070051'),('SP113-2-26','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2024-07-27。本題考身心障礙者權利公約第3條一般原則：包括不歧視、機會均等、無障礙等，為「機會均等」而非「結果均等」。屬公約本文，未經修正；身心障礙者權利公約施行法第2條（公約具國內法律之效力）自 2014-08-20 制定公布、2014-12-03 施行後亦未修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050194'),('SP114-2-26','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2025-07-26。本題考身心障礙者權利公約第27條（工作與就業：平等行使勞動權及工會權、參加技術及職業指導方案並獲得就業服務及職業與繼續訓練、促進職業與專業重建及保留工作和重返工作方案）；於工作場所提供休閒、運動之安排非第27條規定，休閒與體育活動之參與屬第30條範疇。屬公約本文，未經修正；身心障礙者權利公約施行法第2條（公約具國內法律之效力）自 2014-08-20 制定公布、2014-12-03 施行後亦未修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050194'),('SW-107-2-19','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-07-28。本題考身心障礙者權利公約第19條（自立生活及融合社區）：身心障礙者有機會在與其他人平等基礎上選擇居住地點及與何人一起生活，不被迫於特定之居住安排中生活，並得近用居家、住所及其他社區支持服務與為公眾提供之社區服務及設施；選項(B)由家人代為決定居住地點與公約相違。屬公約本文，未經修正；身心障礙者權利公約施行法第2條（公約具國內法律之效力）自 2014-08-20 制定公布、2014-12-03 施行後亦未修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050194'),('SW-113-1-40','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2024-02-04。本題考身心障礙者權利公約第3條（尊重自主、充分有效參與及融合社會）及第19條（自立生活及融合社區，得選擇居住地點，不被迫於特定居住安排中生活，並得近用社區支持服務）：選項(A)(B)(C)與公約相違，選項(D)為正常化原則之概念說明。屬公約本文，未經修正；身心障礙者權利公約施行法第2條（公約具國內法律之效力）自 2014-08-20 制定公布、2014-12-03 施行後亦未修正。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050194');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>11 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL)<>11 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status=b.status, legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id)) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz)<>'4e9790bc9d0d2e0440aecb15d79cabea' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_11, count(*) FILTER (WHERE q.legal_status='changed') changed_0, count(*) total_11 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
